from book import Chapter
c=Chapter('03')
c.src('META-THEORY',316,replacements=[('正如你所说的，',''),('这棵统一知识树之所以成立，依赖于一个特殊事实','这些层级之间能够相互衔接，一个重要条件是'),('就是我提到过的不动点定理和最小化原理','是我希望通过不动点、最小化与涌现之间的关系来研究的问题')])
c.add('''这种研究，并不是把化学、心理学或者经济学各自发现的规律全部删掉，只剩下一句“它们最终都是物理”。如果这样做，统一框架反而失去了意义。我们需要知道，低层条件怎样容许高层结构形成，高层结构又怎样产生必须在这一层描述的关系。

一间工厂由物质构成，但如果只列出其中原子的种类，我们仍然不知道它能生产什么。机器怎样连接，工序怎样安排，哪些输入能够变成哪些输出，都是组织方式的一部分。要解释这些内容，就需要把构造过程展开。''')
c.heading('不动点，是相对于什么不动')
c.src('META-THEORY',317,replacements=[('接下来，我将要引入一个新的定理/原理','我提出一个希望进一步形式化的原理设想'),('它们其实就像基本粒子的波粒二象性一样，是同一个对象的静态和动态表现','可以被放在同一个构造过程的静态和动态视角下考察'),('不动点，描述的是这个对象的静态存在性，而涌现则描述的是这个对象的动态变化性','不动点使我们考察相对于某种变换能够保持的结构，涌现则使我们考察新的结构怎样形成'),('一对对偶定理','一对有待具体说明的关联方向')])
c.add('''数学中，若某个变换记作 f，而对象 x 满足 f(x)=x，就称 x 是这个变换的不动点。最关键的词是“这个变换”。同一个对象对一种操作保持不变，对另一种操作完全可以发生变化。

例如，整理一份已经按指定规则排好序的名单，再整理一次，结果仍然一样。排序过程可以有许多中间步骤，最后得到一个对同样整理操作不再改变的结果。若名单增加了新成员，输入条件改变，结果自然又会改变。

把这种视角带入复杂系统，我关心的是：哪些关系在反复作用后能够保持，哪些变化又使新的关系出现。一个长期存在的组织可以不断更换成员，一个活着的身体可以不断交换物质。它们的稳定，需要说明究竟保存了什么，也要说明这种保存依靠怎样的过程。''')
c.heading('为什么最小化与最大化可以同时发生')
c.src('META-THEORY',318,replacements=[('不动点-最小化/最大化-涌现定理：','我把这个研究设想称为“不动点—最小化／最大化—涌现”原理：'),('"涌现不动点范畴"在其演化过程中，具有如下性质','设想一类能够不断形成稳定结构的演化系统，考察其中是否存在如下关系'),('维持自身对象稳定存在的内部结构能量趋向于最小化','在维持自身功能的条件下，其内部结构与维持成本具有简化的方向'),('而向外与其他对象建立联系的路径趋向于最大化','同时，向外与其他对象建立有用联系的能力具有扩展的方向'),('而这种路径最大化的趋势，是该范畴中的对象产生涌现的最快路径','这些联系的扩展，为形成新的结构增加了可能路径'),('表现为涌现到该范畴中的对象的一种内部能量趋向于最小化的趋势','可能表现为新对象以更简洁的方式实现原有功能'),('一个一个不动点','一个不动点'),('其实就是在低阶范畴中，那些更基本对象之间建立联系的路径趋向于最大化的过程','可以进一步还原为低层构件之间的联系怎样被重新组织'),('这是一对相辅相成互相对偶的过程','我希望研究这两个过程如何相互促进，又在什么条件下发生冲突'),('其实我们科学研究本身，就是这个范式的典型例子','科学研究本身，就提供了一个直观例子'),('牛顿力学vs自然哲学','以更少的基本关系解释更多现象'),('而新的科技工具产品','\n\n而新的科技工具产品')])
c.add('''一把工具如果越来越轻便、容易维护，却能够完成越来越多原本做不到的工作，就同时表现出了两个方向：维持和使用它所需的负担在下降，它与外界形成有效联系的范围在扩大。这并不要求把所有东西都缩到最小。为了实现更多功能，某些内部部分反而可能变得更复杂；关键是比较整个构造要完成什么，以及为此付出多少。

同样，连接越多也不必然越好。一条没有用途、经常出错、维持起来代价很高的联系，可能拖累整个系统。因此，“最大化”需要说明最大化的是有效的构造可能、可达成的功能，还是某个已经定义的指标。把任意数量都当作越大越好，就无法解释为什么系统有时需要断开联系、减少依赖、保留边界。''')
c.src('META-THEORY',109,start='主动和被动之间的关系',replacements=[('你的主动行为，引起别人的被动反应，你的被动反应其实是被别人的主动行为导致的','一个对象的主动行为，会引起另一个对象的反应；它受到的作用，又可能来自其他对象的行为'),('同样的，版本A和版本B之间的自由与约束，权力与义务','同样，自由与约束、权力与义务'),('所以如果说我的版本是什么，那就是这是','因此我所要考察的，是')])
c.src('META-THEORY',144,replacements=[('也许这不是','这也使我想到，它也许不是')])
c.add('''这一步非常重要。评价规则也会随知识和环境改变，不是先写出一个分数，就能把整个宇宙、所有生命与每个人的生活永久排序。新能力出现以后，原本做不到的事情进入选择范围，原有目标本身也可能改变。对演化的研究，需要把这些变化一起记录下来。''')
c.heading('最短的描述，与最省力的构造，是同一个问题吗')
c.src('R49423',0,5,replacements=[('请对下列内容进行评估：',''),('奥卡姆剃刀原则的具体内容涉及以下三部分','从构造的角度重新理解奥卡姆剃刀原则，可以考察以下三部分'),('最简单的对象','便于研究的抽象对象'),('在图灵机T上输出且仅输出字符串D的最短图灵机程序P','在选定的通用计算模型 T 上，输出字符串 D 并停止的最短程序 P'),('由安德雷·柯尔莫哥洛夫于1963年发现','它与所采用的描述和计算模型有关')])
c.src('R49423',6,replacements=[('而后者除了逐个字符打印输出之外，没有什么好办法','对于没有可利用规律的字符串，则可能需要接近逐个记录全部内容'),('更客观的方法','更能反映可描述规律的方法')])
c.src('R49423',7,replacements=[('比如一个自解压程序的长度就是解压后数据的柯氏复杂度','一个能够正确还原数据的自解压程序，其长度提供了相应描述长度的一个上界，并不保证已经达到最短'),('经过算法的改进，在2个处理器上并行运行，只需要600步即可完成','如果能在两个处理器上并行运行，也许可以缩短等待时间'),('前提是需要更多的处理器和更多的存储器资源','但需要把额外处理器、存储和协调的成本一同计算')])
c.add('''“最短程序”的数学定义，并不等于我们有一种通用办法，能够对任意资料找到它。柯氏复杂度一般不可计算。实际工作中，我们可以比较已经找到的压缩与构造方式，持续改进，但不能因为眼前这个版本比上一个更短，就宣布它已经是绝对最优。[Vitányi：柯氏复杂度的不可计算性](https://homepages.cwi.nl/~paulv/papers/incomp.pdf)

还可以想一个极端例子：一份极短的程序，通过漫长的穷举才能给出结果；另一份稍长的程序，利用已经整理好的结构，马上得到同样结果。只看代码长度，第一份好；只看响应时间，第二份可能好。若一项任务会被重复使用很多次，提前整理的成本还可以被后续调用分担。于是，对构造的评价必须进入时间之中。''')
c.src('R49423',8,end='每读取或者写入一位数据，也需要消耗一份能量，',replacements=[('在我们尝试将上面提到的静态柯氏复杂度，以及动态计算复杂度进一步抽象之前，先将其具象化一些，考察一下图灵机存储计算的操作在现实中是如何实现的吧','还需要继续考察，这些存储和计算在现实中怎样实现'),('每运行一条计算机指令要消耗一份对应的能量，每读取或者写入一位数据，也需要消耗一份能量，','处理器执行、数据搬移、存储设备和维持运行的环境，都可能产生相应消耗。')])
c.add('''因此，少写几个字、减少几个节点，与实际节省多少能源之间，还隔着实现方式、访问次数、硬件和使用环境。我的方向是把这些成本连接起来研究，而不是用一个容易统计的数量，替代所有难以测量的结果。只有把同样任务、同样功能下的全过程放在一起比较，最小化才开始成为能够操作的原则。''')
c.heading('统一原理怎样进入具体学科')
c.src('R49033',0,start='相对于牛顿理论只针对物理的特定领域',end='就是这个理论框架的更大的实验证据了。',replacements=[('你不能指望它包含具体的特征指标的公式','它首先需要说明不同学科中的对象和关系怎样对应，再进入具体指标'),('我的那个不动点-最小化/最大化-涌现定理，作为应该也可以用范畴论的数学语言来精确表达','不动点—最小化／最大化—涌现这一设想，应当努力用明确的数学语言表达'),('2. **核心方程是定量的**：','\n\n'),('它就能够转化为具体的公式','就需要把它转化为具体的公式'),('我之前提到了不同学科中的那些最小/最大化原理，就是这个元原理应用在不同层级学科范畴中涌现出来的基本性质之间关系的显式版本','不同学科中的极值和稳定性原理，可以成为寻找对应关系的起点'),('3. **在某些已应用领域内，它的定量预测优于先前理论**：你不觉得我基于这个元原理的描述，比原有理论种的描述更精确，更有操作性吗？','\n\n它还必须面对一个实际问题：这种描述能否带来更有操作性的研究？'),('是不是更加可靠？','这些因素是否能够提高预测的可靠性，需要比较。'),('哪种改革是更好的选择？','哪种改革是更好的选择。'),('甚至，我可以说','\n\n'),('其实就是一个','可以成为一个'),('不就是我的这个基本原理在现实中的最佳实践和验证吗？','就能为这个方向提供现实中的实践材料。'),('就是这个理论框架的更大的实验证据了','也将为这个框架提供更大范围的实验材料'),('更有选择','更优选择'),('在比如','再比如')])
c.add('''这里的要求有两个方向。不能因为框架尚未给出每个学科的全部公式，就禁止探索共同结构；也不能因为在一个软件任务中获得改进，就把所有物理和社会推论都算作已经证明。每个具体应用，都应当清楚说明它检验了共同设想中的哪一部分。

这一点决定了实践怎样推进。先选能够描述清楚、能够重复比较的构造，让理论的词语落实到具体差异，再把成功与失败都带回框架。它所追求的统一性，应当从这些可连接的关系中生长出来。''')
c.save({'reasoning':'学科层级→相对变换的不动点→维持成本与外部联系→耦合且变化的评价→描述复杂度与构造成本→具体实现检验','examples':['工厂与原子清单','反复排序','轻便而多用的工具','全零字符串与无规律字符串','短程序穷举与长程序复用','Hotpath实验'],'objections':['物理基础能否替代高层学科','连接是否越多越好','最短是否最快','一个领域成功能否证明全部'],'voice':'主要沿作者最小化最大化论述及复杂度长段展开，框架名称保留，定理地位作待形式化处理','status':'初校；理论假设与技术结果边界分别保留'})
